mapper.select:
/* saleson.batch.BatchLogMapper.getBatchLogListCount */ SELECT COUNT(1) FROM OP_BATCH_EXECUTION BE , OP_BATCH_JOB BJ WHERE 1 = 1 AND BE.BATCH_TYPE LIKE '%' || BJ.JOB_METHOD || '%'
AND JOB_NAME LIKE CONCAT('%', #{query}, '%')
AND BE.execution_date BETWEEN NVL(#{searchStartDate} , to_char(sys_date, 'YYYYMMDD')) AND NVL(#{searchEndDate} , to_char(sys_date, 'YYYYMMDD'))
ORDER BY BE.EXECUTION_DATE DESC, BE.START_TIME, BE.END_TIME;
